define behavior for ZR_PurchaseOrder_TP alias PurchaseOrder
{
  /* Clean Core Native Event Definition */
  event Created parameter ZD_PO_Event_Payload;
  event Changed parameter ZD_PO_Event_Payload;

  determination publishEvent on modify { create; }
}

// SAP CAP Event Handler (BTP Runtime)
messaging.on('sap.s4.beh.purchaseorder.v1.PurchaseOrder.Created.v1', async (msg) => {
  const { PurchaseOrder, Supplier } = msg.data;
  console.log(`[BTP Service] Processing PO ${PurchaseOrder} from Supplier ${Supplier}`);
  await triggerLogisticsSync(PurchaseOrder);
  msg.ack();
});
